@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; } = 0;
    private int HighestCompletedStep { get; set; } = -1;
    private bool IsLoading { get; set; }
    private string ErrorMessage { get; set; } = "";
    private bool IsSubmitted { get; set; }
    private int SubmittedApplicationId { get; set; }

    // Step 1: Personal Info
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2: Work History
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string CoverLetter { get; set; } = "";

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (step <= HighestCompletedStep) return "completed";
        return "";
    }

    private void GoToStep(int step)
    {
        if (step <= HighestCompletedStep)
        {
            ErrorMessage = "";
            CurrentStep = step;
        }
    }

    private void PreviousStep()
    {
        ErrorMessage = "";
        CurrentStep--;
    }

    private void AdvanceStep()
    {
        if (CurrentStep > HighestCompletedStep)
            HighestCompletedStep = CurrentStep;
        CurrentStep++;
        ErrorMessage = "";
    }

    // Step 1 validation
    private async Task NextFromPersonalInfo()
    {
        ErrorMessage = "";
        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Please fill in all required fields.";
            return;
        }

        IsLoading = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
            AdvanceStep();
        }
        finally
        {
            IsLoading = false;
        }
    }

    // Step 2 validation
    private void NextFromWorkHistory()
    {
        ErrorMessage = "";
        foreach (var entry in WorkEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
            {
                ErrorMessage = "Please fill in company name, job title, and start date for all positions.";
                return;
            }
        }
        AdvanceStep();
    }

    // Step 3 validation
    private void NextFromReferences()
    {
        ErrorMessage = "";
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }
        AdvanceStep();
    }

    // Step 4 validation
    private void NextFromCoverLetter()
    {
        ErrorMessage = "";
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "Please enter a cover letter.";
            return;
        }
        AdvanceStep();
    }

    // Work History helpers
    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.RemoveAt(index);
    }

    private void UpdateWorkEntry(int index, string? company = null, string? title = null, string? description = null)
    {
        var entry = WorkEntries[index];
        if (company != null) entry.Company = company;
        if (title != null) entry.Title = title;
        if (description != null) entry.Description = description;
    }

    private void UpdateWorkEntryStartDate(int index, string? value)
    {
        if (DateTime.TryParse(value, out var date))
            WorkEntries[index].StartDate = date;
    }

    private void UpdateWorkEntryEndDate(int index, string? value)
    {
        if (DateTime.TryParse(value, out var date))
            WorkEntries[index].EndDate = date;
    }

    private void ToggleCurrentPosition(int index, bool isCurrent)
    {
        WorkEntries[index].IsCurrent = isCurrent;
        if (isCurrent) WorkEntries[index].EndDate = null;
    }

    // References helpers
    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void UpdateReference(int index, string? name = null, string? relationship = null, string? email = null, string? phone = null)
    {
        var r = References[index];
        if (name != null) r.Name = name;
        if (relationship != null) r.Relationship = relationship;
        if (email != null) r.Email = email;
        if (phone != null) r.Phone = phone;
    }

    // Submit
    private async Task SubmitApplication()
    {
        IsLoading = true;
        ErrorMessage = "";
        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var references = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, workHistory, references, CoverLetter);

            SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsLoading = false;
        }
    }

    // View models for mutable state
    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

