@page "/apply"
@rendermode InteractiveServer
@using sv_2a2363bb826944feb06354ae00476443.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

<!-- Step Indicator Bar -->
<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => GoToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger mt-3">@ErrorMessage</div>
}

<!-- Step 1: Personal Info -->
@if (CurrentStep == 0)
{
    <div class="form-section">
        <h3>Personal Information</h3>
        <div class="mb-3">
            <label class="form-label">Full Name *</label>
            <input type="text" class="form-control" @bind="FullName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control" @bind="Email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Phone *</label>
            <input type="tel" class="form-control" @bind="Phone" />
        </div>
        <div class="mb-3">
            <label class="form-label">Address *</label>
            <textarea class="form-control" @bind="Address"></textarea>
        </div>
        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@IsLoading">
                @if (IsLoading) { <span>Validating...</span> } else { <span>Next</span> }
            </button>
        </div>
    </div>
}

<!-- Step 2: Work History -->
@if (CurrentStep == 1)
{
    <div class="form-section">
        <h3>Work History</h3>
        @for (int i = 0; i < WorkEntries.Count; i++)
        {
            var index = i;
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5>Position @(index + 1)</h5>
                    @if (WorkEntries.Count > 1)
                    {
                        <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                </div>
                <div class="mb-3">
                    <label class="form-label">Company Name *</label>
                    <input type="text" class="form-control" value="@WorkEntries[index].Company"
                           @onchange="(e) => UpdateWorkEntry(index, company: e.Value?.ToString())" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Job Title *</label>
                    <input type="text" class="form-control" value="@WorkEntries[index].Title"
                           @onchange="(e) => UpdateWorkEntry(index, title: e.Value?.ToString())" />
                </div>
                <div class="row mb-3">
                    <div class="col-md-6">
                        <label class="form-label">Start Date *</label>
                        <input type="date" class="form-control" value="@WorkEntries[index].StartDate?.ToString("yyyy-MM-dd")"
                               @onchange="(e) => UpdateWorkEntryStartDate(index, e.Value?.ToString())" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">End Date</label>
                        <input type="date" class="form-control" value="@WorkEntries[index].EndDate?.ToString("yyyy-MM-dd")"
                               disabled="@WorkEntries[index].IsCurrent"
                               @onchange="(e) => UpdateWorkEntryEndDate(index, e.Value?.ToString())" />
                        <div class="form-check mt-1">
                            <input class="form-check-input" type="checkbox" checked="@WorkEntries[index].IsCurrent"
                                   @onchange="(e) => ToggleCurrentPosition(index, (bool)(e.Value ?? false))" />
                            <label class="form-check-label">Currently working here</label>
                        </div>
                    </div>
                </div>
                <div class="mb-3">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" value="@WorkEntries[index].Description"
                              @onchange="(e) => UpdateWorkEntry(index, description: e.Value?.ToString())"></textarea>
                </div>
            </div>
        }
        <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
        </div>
    </div>
}

<!-- Step 3: References -->
@if (CurrentStep == 2)
{
    <div class="form-section">
        <h3>References</h3>
        @for (int i = 0; i < References.Count; i++)
        {
            var index = i;
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5>Reference @(index + 1)</h5>
                    @if (References.Count > 2)
                    {
                        <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                </div>
                <div class="mb-3">
                    <label class="form-label">Name *</label>
                    <input type="text" class="form-control" value="@References[index].Name"
                           @onchange="(e) => UpdateReference(index, name: e.Value?.ToString())" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Relationship *</label>
                    <input type="text" class="form-control" value="@References[index].Relationship"
                           @onchange="(e) => UpdateReference(index, relationship: e.Value?.ToString())" />
                </div>
                <div class="row mb-3">
                    <div class="col-md-6">
                        <label class="form-label">Email *</label>
                        <input type="email" class="form-control" value="@References[index].Email"
                               @onchange="(e) => UpdateReference(index, email: e.Value?.ToString())" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Phone *</label>
                        <input type="tel" class="form-control" value="@References[index].Phone"
                               @onchange="(e) => UpdateReference(index, phone: e.Value?.ToString())" />
                    </div>
                </div>
            </div>
        }
        @if (References.Count < 3)
        {
            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
        </div>
    </div>
}

<!-- Step 4: Cover Letter -->
@if (CurrentStep == 3)
{
    <div class="form-section">
        <h3>Cover Letter</h3>
        <div class="mb-3">
            <textarea class="form-control" rows="12" @bind="CoverLetter" @bind:event="oninput" maxlength="2000"></textarea>
            <div class="text-muted mt-1">@CoverLetter.Length / 2000 characters</div>
        </div>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
        </div>
    </div>
}

<!-- Step 5: Review & Submit -->
@if (CurrentStep == 4)
{
    @if (IsSubmitted)
    {
        <div class="form-section text-center">
            <h3 class="text-success">Application Submitted!</h3>
            <p class="fs-5">Your application has been submitted successfully.</p>
            <p>Application ID: <strong>@SubmittedApplicationId</strong></p>
        </div>
    }
    else
    {
        <div class="form-section">
            <h3>Review & Submit</h3>

            <!-- Personal Info Review -->
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Personal Information</h5>
                    <a href="javascript:void(0)" @onclick="() => GoToStep(0)">Edit</a>
                </div>
                <dl class="row mb-0">
                    <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@FullName</dd>
                    <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@Email</dd>
                    <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@Phone</dd>
                    <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@Address</dd>
                </dl>
            </div>

            <!-- Work History Review -->
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Work History</h5>
                    <a href="javascript:void(0)" @onclick="() => GoToStep(1)">Edit</a>
                </div>
                @foreach (var entry in WorkEntries)
                {
                    <div class="mb-2 ps-2 border-start border-3">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <small class="text-muted">
                            @entry.StartDate?.ToString("MMM yyyy") &mdash;
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mb-0 mt-1">@entry.Description</p>
                        }
                    </div>
                }
            </div>

            <!-- References Review -->
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>References</h5>
                    <a href="javascript:void(0)" @onclick="() => GoToStep(2)">Edit</a>
                </div>
                @foreach (var reference in References)
                {
                    <div class="mb-2">
                        <strong>@reference.Name</strong> (@reference.Relationship)<br />
                        <small>@reference.Email &bull; @reference.Phone</small>
                    </div>
                }
            </div>

            <!-- Cover Letter Review -->
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Cover Letter</h5>
                    <a href="javascript:void(0)" @onclick="() => GoToStep(3)">Edit</a>
                </div>
                <p style="white-space: pre-wrap;">@CoverLetter</p>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@IsLoading">
                    @if (IsLoading) { <span>Submitting...</span> } else { <span>Submit Application</span> }
                </button>
            </div>
        </div>
    }
}

<style>
    .step-indicator {
        display: flex;
        align-items: center;
        justify-content: center;
        margin: 2rem 0;
        flex-wrap: wrap;
        gap: 0.25rem;
    }
