+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
+        </div>
+    </div>
+}
+
+<!-- Step 3: References -->
+@if (CurrentStep == 2)
+{
+    <div class="form-section">
+        <h3>References</h3>
+        @for (int i = 0; i < References.Count; i++)
+        {
+            var index = i;
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center mb-2">
+                    <h5>Reference @(index + 1)</h5>
+                    @if (References.Count > 2)
+                    {
+                        <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveReference(index)">Remove</button>
+                    }
+                </div>
+                <div class="mb-3">
+                    <label class="form-label">Name *</label>
+                    <input type="text" class="form-control" value="@References[index].Name"
+                           @onchange="(e) => UpdateReference(index, name: e.Value?.ToString())" />
+                </div>
+                <div class="mb-3">
+                    <label class="form-label">Relationship *</label>
+                    <input type="text" class="form-control" value="@References[index].Relationship"
+                           @onchange="(e) => UpdateReference(index, relationship: e.Value?.ToString())" />
+                </div>
+                <div class="row mb-3">
+                    <div class="col-md-6">
+                        <label class="form-label">Email *</label>
+                        <input type="email" class="form-control" value="@References[index].Email"
+                               @onchange="(e) => UpdateReference(index, email: e.Value?.ToString())" />
+                    </div>
+                    <div class="col-md-6">
+                        <label class="form-label">Phone *</label>
+                        <input type="tel" class="form-control" value="@References[index].Phone"
+                               @onchange="(e) => UpdateReference(index, phone: e.Value?.ToString())" />
+                    </div>
+                </div>
+            </div>
+        }
+        @if (References.Count < 3)
+        {
+            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
+        }
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
+        </div>
+    </div>
+}
+
+<!-- Step 4: Cover Letter -->
+@if (CurrentStep == 3)
+{
+    <div class="form-section">
+        <h3>Cover Letter</h3>
+        <div class="mb-3">
+            <textarea class="form-control" rows="12" @bind="CoverLetter" @bind:event="oninput" maxlength="2000"></textarea>
+            <div class="text-muted mt-1">@CoverLetter.Length / 2000 characters</div>
+        </div>
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
+        </div>
+    </div>
+}
+
+<!-- Step 5: Review & Submit -->
+@if (CurrentStep == 4)
+{
+    @if (IsSubmitted)
+    {
+        <div class="form-section text-center">
+            <h3 class="text-success">Application Submitted!</h3>
+            <p class="fs-5">Your application has been submitted successfully.</p>
+            <p>Application ID: <strong>@SubmittedApplicationId</strong></p>
+        </div>
+    }
+    else
+    {
+        <div class="form-section">
+            <h3>Review & Submit</h3>
+
+            <!-- Personal Info Review -->
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>Personal Information</h5>
+                    <a href="javascript:void(0)" @onclick="() => GoToStep(0)">Edit</a>
+                </div>
+                <dl class="row mb-0">
+                    <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@FullName</dd>
+                    <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@Email</dd>
+                    <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@Phone</dd>
+                    <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@Address</dd>
+                </dl>
+            </div>
+
+            <!-- Work History Review -->
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>Work History</h5>
+                    <a href="javascript:void(0)" @onclick="() => GoToStep(1)">Edit</a>
+                </div>
+                @foreach (var entry in WorkEntries)
+                {
+                    <div class="mb-2 ps-2 border-start border-3">
+                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
+                        <small class="text-muted">
+                            @entry.StartDate?.ToString("MMM yyyy") &mdash;
+                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
+                        </small>
+                        @if (!string.IsNullOrWhiteSpace(entry.Description))
+                        {
+                            <p class="mb-0 mt-1">@entry.Description</p>
+                        }
+                    </div>
+                }
+            </div>
+
+            <!-- References Review -->
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>References</h5>
+                    <a href="javascript:void(0)" @onclick="() => GoToStep(2)">Edit</a>
+                </div>
+                @foreach (var reference in References)
+                {
+                    <div class="mb-2">
+                        <strong>@reference.Name</strong> (@reference.Relationship)<br />
+                        <small>@reference.Email &bull; @reference.Phone</small>
+                    </div>
+                }
+            </div>
+
+            <!-- Cover Letter Review -->
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>Cover Letter</h5>
+                    <a href="javascript:void(0)" @onclick="() => GoToStep(3)">Edit</a>
+                </div>
+                <p style="white-space: pre-wrap;">@CoverLetter</p>
+            </div>
+
+            <div class="d-flex justify-content-between">
+                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@IsLoading">
+                    @if (IsLoading) { <span>Submitting...</span> } else { <span>Submit Application</span> }
+                </button>
+            </div>
+        </div>
+    }
+}
+
+<style>
+    .step-indicator {
+        display: flex;
+        align-items: center;
+        justify-content: center;
+        margin: 2rem 0;
+        flex-wrap: wrap;
+        gap: 0.25rem;
+    }
+    .step {
+        display: flex;
+        flex-direction: column;
+        align-items: center;
+        cursor: default;
+        opacity: 0.4;
+        transition: opacity 0.2s;
+    }
+    .step.active {
+        opacity: 1;
+    }
+    .step.completed {
+        opacity: 1;
+        cursor: pointer;
+    }
+    .step-circle {
+        width: 36px;
+        height: 36px;
+        border-radius: 50%;
+        background: #dee2e6;
+        display: flex;
+        align-items: center;
+        justify-content: center;
+        font-weight: bold;
+        font-size: 0.9rem;
+    }
+    .step.active .step-circle {
+        background: #0d6efd;
+        color: white;
+    }
+    .step.completed .step-circle {
+        background: #198754;
+        color: white;
+    }
+    .step-label {
+        font-size: 0.75rem;
+        margin-top: 0.25rem;
+        text-align: center;
+        max-width: 80px;
+    }
+    .step-connector {
+        flex: 1;
+        height: 2px;
+        background: #dee2e6;
+        min-width: 20px;
+        max-width: 60px;
+        margin: 0 0.25rem;
+        align-self: center;
+        margin-bottom: 1.2rem;
+    }
+    .step-connector.completed {
+        background: #198754;
+    }
+    .form-section {
+        max-width: 720px;
+        margin: 0 auto;
+    }
+</style>
+
+@code {
+    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+
+    private int CurrentStep { get; set; } = 0;
+    private int HighestCompletedStep { get; set; } = -1;
+    private bool IsLoading { get; set; }
+    private string ErrorMessage { get; set; } = "";
+    private bool IsSubmitted { get; set; }
+    private int SubmittedApplicationId { get; set; }
+
+    // Step 1: Personal Info
+    private string FullName { get; set; } = "";
+    private string Email { get; set; } = "";
+    private string Phone { get; set; } = "";
+    private string Address { get; set; } = "";
+
+    // Step 2: Work History
+    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };
+
+    // Step 3: References
+    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4: Cover Letter
+    private string CoverLetter { get; set; } = "";
+
+    private string GetStepClass(int step)
+    {
+        if (step == CurrentStep) return "active";
+        if (step <= HighestCompletedStep) return "completed";
+        return "";
+    }
+
+    private void GoToStep(int step)
+    {
+        if (step <= HighestCompletedStep)
+        {
+            ErrorMessage = "";
+            CurrentStep = step;
+        }
+    }
+
+    private void PreviousStep()
+    {
+        ErrorMessage = "";
+        CurrentStep--;
+    }
+
+    private void AdvanceStep()
+    {
+        if (CurrentStep > HighestCompletedStep)
+            HighestCompletedStep = CurrentStep;
+        CurrentStep++;
+        ErrorMessage = "";
+    }
+
+    // Step 1 validation
+    private async Task NextFromPersonalInfo()
+    {
+        ErrorMessage = "";
+        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
+            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
+        {
+            ErrorMessage = "Please fill in all required fields.";
+            return;
+        }
+
+        IsLoading = true;
+        try
+        {
+            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
+            if (!emailValid)
+            {
+                ErrorMessage = "Please enter a valid email address.";
+                return;
+            }
+            AdvanceStep();
+        }
+        finally
+        {
+            IsLoading = false;
+        }
+    }
+
+    // Step 2 validation
+    private void NextFromWorkHistory()
+    {
+        ErrorMessage = "";
+        foreach (var entry in WorkEntries)
+        {
+            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
+            {
+                ErrorMessage = "Please fill in company name, job title, and start date for all positions.";
+                return;
+            }
+        }
+        AdvanceStep();
+    }
+
+    // Step 3 validation
+    private void NextFromReferences()
+    {
+        ErrorMessage = "";
+        foreach (var r in References)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
+                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
+            {
+                ErrorMessage = "Please fill in all fields for each reference.";
+                return;
+            }
+        }
+        AdvanceStep();
+    }
+
+    // Step 4 validation
+    private void NextFromCoverLetter()
+    {
+        ErrorMessage = "";
+        if (string.IsNullOrWhiteSpace(CoverLetter))
+        {
+            ErrorMessage = "Please enter a cover letter.";
+            return;
+        }
+        AdvanceStep();
+    }
+
+    // Work History helpers
+    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());
+
+    private void RemoveWorkEntry(int index)
+    {
+        if (WorkEntries.Count > 1)
+            WorkEntries.RemoveAt(index);
+    }
+
+    private void UpdateWorkEntry(int index, string? company = null, string? title = null, string? description = null)
+    {
+        var entry = WorkEntries[index];
+        if (company != null) entry.Company = company;
+        if (title != null) entry.Title = title;
+        if (description != null) entry.Description = description;
+    }
+
+    private void UpdateWorkEntryStartDate(int index, string? value)
+    {
+        if (DateTime.TryParse(value, out var date))
+            WorkEntries[index].StartDate = date;
+    }
+
+    private void UpdateWorkEntryEndDate(int index, string? value)
+    {
+        if (DateTime.TryParse(value, out var date))
+            WorkEntries[index].EndDate = date;
+    }
+
+    private void ToggleCurrentPosition(int index, bool isCurrent)
+    {
+        WorkEntries[index].IsCurrent = isCurrent;
+        if (isCurrent) WorkEntries[index].EndDate = null;
+    }
+
+    // References helpers
+    private void AddReference()
+    {
+        if (References.Count < 3)
+            References.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (References.Count > 2)
+            References.RemoveAt(index);
+    }
+
+    private void UpdateReference(int index, string? name = null, string? relationship = null, string? email = null, string? phone = null)
+    {
+        var r = References[index];
+        if (name != null) r.Name = name;
+        if (relationship != null) r.Relationship = relationship;
+        if (email != null) r.Email = email;
+        if (phone != null) r.Phone = phone;
+    }
+
+    // Submit
+    private async Task SubmitApplication()
+    {
+        IsLoading = true;
+        ErrorMessage = "";
+        try
+        {
+            var personal = new PersonalInfo(FullName, Email, Phone, Address);
+            var workHistory = new WorkHistory(WorkEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
+            var references = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+            var application = new JobApplication(personal, workHistory, references, CoverLetter);
+
+            SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
+            IsSubmitted = true;
+        }
+        catch (Exception ex)
+        {
+            ErrorMessage = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            IsLoading = false;
+        }
+    }
+
+    // View models for mutable state
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = "";
+        public string Title { get; set; } = "";
+        public DateTime? StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = "";
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = "";
+        public string Relationship { get; set; } = "";
+        public string Email { get; set; } = "";
+        public string Phone { get; set; } = "";
+    }
+}
+
